#include <string>
#include <unordered_map>
#include <vector>

using namespace std;

class Solution {
public:
    string evaluate(string s, vector<vector<string>>& knowledge) {
        unordered_map<string, string> map;
        for (auto& k : knowledge)
            map[k[0]] = k[1];

        string res, key;
        bool inBracket = false;
        for (char c : s) {
            if (c == '(') {
                key.clear();
                inBracket = true;
            } else if (c == ')') {
                res += map.count(key) ? map[key] : "?";
                inBracket = false;
            } else if (inBracket) {
                key += c;
            } else {
                res += c;
            }
        }
        return res;
    }
};
